/* Global border-box reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.card {
  width: 300px;
  padding: 20px;
  border: 2px solid #333;
  /* Total element width remains exactly 300px because of border-box */
}

.grid-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.flex-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
